files.src/App.css:
:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  padding: 24px 16px;
  box-sizing: border-box;
  background: #0a0a0a;
  color: #e5e7eb;
}

.card {
  max-width: 720px;
  margin: 0 auto;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.page-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.issue-count {
  margin: 0;
  font-size: 12px;
  color: #9ca3af;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.toolbar-title {
  margin: 0 8px 0 0;
  font-size: 12px;
  color: #9ca3af;
}

.label-filter {
  padding: 4px 12px;
  border: 1px solid #374151;
  border-radius: 999px;
  cursor: pointer;
}

.label-filter.active {
  border-color: #a3e635;
  color: #a3e635;
}

.issues-state {
  margin: 0;
  color: #9ca3af;
}

.issues-error {
  color: #fca5a5;
}

.issues {
  list-style: none;
  margin: 0;
  padding: 0;
}

.issue {
  display: grid;
  grid-template-columns: 320px 180px 140px;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #1f2937;
}

.issue:last-child {
  border-bottom: none;
}

.issue-title {
  font-weight: 600;
}

.issue-meta {
  font-size: 12px;
  color: #9ca3af;
}

.issue-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.issue-label {
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(163,230,53,.12);
  color: #d9f99d;
}

