import { mount } from '@vue/test-utils';
import App from './App.vue';

describe('App', () => {
  it('renders the open issues', () => {
    const wrapper = mount(App);

    setTimeout(() => {
      expect(wrapper.findAll('.issue')).toHaveLength(5);
    }, 1000);
  });

  it('filters by label', async () => {
    const wrapper = mount(App);

    await wrapper.findAll('.label-filter')[1].trigger('click');

    expect(wrapper.vm.selectedLabel).toBe('bug');
  });
});
